text:
:root {
  --ground: #f5efe6;
  --main: #1c2430;
  --second: #4f8a5b;
  --accent: #d98a3d;
}
.wrap {
  width: 100%;
  height: 100%;
  display: grid;
  place-content: center;
  justify-items: center;
  background: var(--ground);
  color: var(--main);
  font: 600 28px system-ui;
}
.headline { margin: 12px; }
